			"Pill-shaped AI prompt bar with voice and audio icons. Best for a tall pill prompt bar: a plus opening an upward tools menu with a More submenu, and mic and voice buttons at the far end.",
		file: "input-group-34",
		source:
			'import * as React from "react";\nimport {\n\tAppWindowIcon,\n\tAudioLinesIcon,\n\tBookOpenIcon,\n\tBrainIcon,\n\tGlobeIcon,\n\tImageIcon,\n\tLayoutDashboardIcon,\n\tMicIcon,\n\tPaperclipIcon,\n\tPlusIcon,\n\tSearchIcon,\n\tShoppingBagIcon,\n\tSparklesIcon,\n} from "lucide-react";\nimport {\n\tDropdownMenu,\n\tDropdownMenuContent,\n\tDropdownMenuItem,\n\tDropdownMenuSeparator,\n\tDropdownMenuSub,\n\tDropdownMenuSubContent,\n\tDropdownMenuSubTrigger,\n\tDropdownMenuTrigger,\n} from "@workspace/ui/components/dropdown-menu";\nimport { Field } from "@workspace/ui/components/field";\nimport { InputGroup, InputGroupAddon, InputGroupButton, InputGroupInput } from "@workspace/ui/components/input-group";\n\nexport function InputGroup34Example(): React.JSX.Element {\n\treturn (\n\t\t<Field className="max-w-3xl">\n\t\t\t<InputGroup className="h-14 rounded-full border bg-background p-1.5">\n\t\t\t\t<InputGroupAddon className="border-none pl-2">\n\t\t\t\t\t<DropdownMenu>\n\t\t\t\t\t\t<DropdownMenuTrigger render={<InputGroupButton variant="ghost" size="icon-sm" className="size-10 rounded-full text-muted-foreground hover:text-foreground" />}>\n\t\t\t\t\t\t\t<PlusIcon className="size-6" />\n\t\t\t\t\t\t</DropdownMenuTrigger>\n\t\t\t\t\t\t<DropdownMenuContent side="top" align="start" sideOffset={12} className="w-56">\n\t\t\t\t\t\t\t<DropdownMenuItem>\n\t\t\t\t\t\t\t\t<PaperclipIcon />\n\t\t\t\t\t\t\t\t<span>Add photos & files</span>\n\t\t\t\t\t\t\t</DropdownMenuItem>\n\t\t\t\t\t\t\t<DropdownMenuSeparator className="-mx-3" />\n\t\t\t\t\t\t\t<DropdownMenuItem>\n\t\t\t\t\t\t\t\t<ImageIcon />\n\t\t\t\t\t\t\t\t<span>Create image</span>\n\t\t\t\t\t\t\t</DropdownMenuItem>\n\t\t\t\t\t\t\t<DropdownMenuItem>\n\t\t\t\t\t\t\t\t<BrainIcon />\n\t\t\t\t\t\t\t\t<span>Thinking</span>\n\t\t\t\t\t\t\t</DropdownMenuItem>\n\t\t\t\t\t\t\t<DropdownMenuItem>\n\t\t\t\t\t\t\t\t<SearchIcon />\n\t\t\t\t\t\t\t\t<span>Deep research</span>\n\t\t\t\t\t\t\t</DropdownMenuItem>\n\t\t\t\t\t\t\t<DropdownMenuItem>\n\t\t\t\t\t\t\t\t<ShoppingBagIcon />\n\t\t\t\t\t\t\t\t<span>Shopping research</span>\n\t\t\t\t\t\t\t</DropdownMenuItem>\n\t\t\t\t\t\t\t<DropdownMenuSub>\n\t\t\t\t\t\t\t\t<DropdownMenuSubTrigger>\n\t\t\t\t\t\t\t\t\t<SparklesIcon />\n\t\t\t\t\t\t\t\t\t<span>More</span>\n\t\t\t\t\t\t\t\t</DropdownMenuSubTrigger>\n\t\t\t\t\t\t\t\t<DropdownMenuSubContent className="w-44">\n\t\t\t\t\t\t\t\t\t<DropdownMenuItem>\n\t\t\t\t\t\t\t\t\t\t<BookOpenIcon />\n\t\t\t\t\t\t\t\t\t\t<span>Study and learn</span>\n\t\t\t\t\t\t\t\t\t</DropdownMenuItem>\n\t\t\t\t\t\t\t\t\t<DropdownMenuItem>\n\t\t\t\t\t\t\t\t\t\t<GlobeIcon />\n\t\t\t\t\t\t\t\t\t\t<span>Web search</span>\n\t\t\t\t\t\t\t\t\t</DropdownMenuItem>\n\t\t\t\t\t\t\t\t\t<DropdownMenuItem>\n\t\t\t\t\t\t\t\t\t\t<LayoutDashboardIcon />\n\t\t\t\t\t\t\t\t\t\t<span>Canvas</span>\n\t\t\t\t\t\t\t\t\t</DropdownMenuItem>\n\t\t\t\t\t\t\t\t\t<DropdownMenuItem>\n\t\t\t\t\t\t\t\t\t\t<AppWindowIcon />\n\t\t\t\t\t\t\t\t\t\t<span>Explore apps</span>\n\t\t\t\t\t\t\t\t\t</DropdownMenuItem>\n\t\t\t\t\t\t\t\t</DropdownMenuSubContent>\n\t\t\t\t\t\t\t</DropdownMenuSub>\n\t\t\t\t\t\t</DropdownMenuContent>\n\t\t\t\t\t</DropdownMenu>\n\t\t\t\t</InputGroupAddon>\n\n\t\t\t\t<InputGroupInput placeholder="Ask anything" className="border-none px-2 text-lg shadow-none placeholder:text-muted-foreground/70 focus-visible:ring-0" />\n\n\t\t\t\t<InputGroupAddon align="inline-end" className="gap-2 border-none pr-1">\n\t\t\t\t\t<InputGroupButton variant="ghost" className="size-11 rounded-full text-muted-foreground hover:text-foreground">\n\t\t\t\t\t\t<MicIcon className="size-5" />\n\t\t\t\t\t</InputGroupButton>\n\t\t\t\t\t<InputGroupButton variant="default" className="size-11 rounded-full bg-black text-white hover:bg-black/90">\n\t\t\t\t\t\t<AudioLinesIcon className="size-5" />\n\t\t\t\t\t</InputGroupButton>\n\t\t\t\t</InputGroupAddon>\n\t\t\t</InputGroup>\n\t\t</Field>\n\t);\n}\n',
